'use strict';
// Recipes: the small, recurring pieces of shell scripts (and of exam solutions). Every example is run for real.
const SAMPLE_LOG = 'cat > access.log << \'EOF\'\n10.0.0.1 - - [01/Jun/2024:10:00:01 +0000] "GET /index.html HTTP/1.1" 200 512\n10.0.0.2 - - [01/Jun/2024:10:00:05 +0000] "GET /missing HTTP/1.1" 404 128\n10.0.0.1 - - [01/Jun/2024:10:01:10 +0000] "POST /login HTTP/1.1" 200 64\n10.0.0.3 - - [01/Jun/2024:11:02:00 +0000] "GET /index.html HTTP/1.1" 200 512\n10.0.0.1 - - [01/Jun/2024:11:03:30 +0000] "GET /admin HTTP/1.1" 403 99\nEOF\n';
MANUAL.add('patterns', [
  {
    name: 'Usage message and argument count', key: 'patterns-usage', kind: 'concept', aliases: ['usage', 'usage message', 'usage pattern', 'die/usage pattern', 'argument count', 'check number of arguments', 'wrong number of arguments', 'die', 'die function', '$# -ne', '$# -lt', 'missing argument', 'missing operand', 'print usage'],
    summary: 'Check how many arguments a script got, print a usage line on stderr and exit with a non-zero status.',
    synopsis: ['[ $# -eq 2 ] || { echo "usage: $0 SRC DST" >&2; exit 1; }', 'die() { echo "$0: $*" >&2; exit 1; }'],
    desc: ['The first lines of nearly every script. If the number of arguments (`$#`) is wrong, explain how to call it, **on standard error** (`>&2`, so the message does not pollute a pipe) and **exit with a non-zero status** (1, or 2 for "misuse"). Use `$0` for the script name so the message stays right if the file is renamed (`${0##*/}` strips the directory). A small `die` function avoids repeating the two lines. Check the **count first**, validate the **content** afterwards (see the validation pattern).'],
    sections: [{ title: 'Template', code: '#!/bin/bash\nusage() { echo "usage: ${0##*/} SOURCE DEST" >&2; exit 2; }\ndie()   { echo "${0##*/}: $*" >&2; exit 1; }\n\n[ $# -eq 2 ] || usage\n[ -e "$1" ]  || die "$1: no such file"\n# ... the real work ...' }],
    examples: [
      { title: 'Exactly N arguments', cmd: 'cat > s.sh << \'EOF\'\nif [ $# -ne 2 ]; then\n  echo "usage: $0 SOURCE DEST" >&2\n  exit 1\nfi\necho "copying $1 to $2"\nEOF\nbash s.sh a; echo "status: $?"\nbash s.sh a b; echo "status: $?"', fails: true },
      { title: 'At least one argument', cmd: 'cat > s.sh << \'EOF\'\n[ $# -ge 1 ] || { echo "usage: $0 FILE..." >&2; exit 1; }\nfor f in "$@"; do echo "processing $f"; done\nEOF\nbash s.sh; echo "status: $?"\nbash s.sh a b', fails: true },
      { title: 'A die() helper', cmd: 'cat > s.sh << \'EOF\'\ndie() { echo "$0: error: $*" >&2; exit 1; }\n[ $# -eq 1 ] || die "need exactly one argument, got $#"\n[ -d "$1" ] || die "$1 is not a directory"\necho "$1 is fine"\nEOF\nbash s.sh; echo "status: $?"\nbash s.sh /nonexistent; echo "status: $?"\nbash s.sh /tmp; echo "status: $?"', fails: true },
      { title: 'Show the script name without the path', cmd: 'cat > s.sh << \'EOF\'\necho "usage: ${0##*/} FILE" >&2\nEOF\nbash ./s.sh 2>&1\nmkdir bin; cp s.sh bin/; bash bin/s.sh 2>&1', note: '`${0##*/}` is `basename "$0"` without a new process.' },
      { title: 'Help option', cmd: 'cat > s.sh << \'EOF\'\ncase "$1" in -h|--help) echo "usage: $0 [-h] FILE"; exit 0 ;; esac\n[ $# -eq 1 ] || { echo "usage: $0 [-h] FILE" >&2; exit 2; }\necho "ok"\nEOF\nbash s.sh --help; echo "status: $?"\nbash s.sh; echo "status: $?"', fails: true },
      { title: 'The message goes to stderr, not stdout', cmd: 'printf \'echo "usage: $0 FILE" >&2\\nexit 1\\n\' > s.sh\nbash s.sh 2>/dev/null; echo "(nothing shown: the message was on stderr)"\nbash s.sh 2>&1 >/dev/null', fails: true, note: 'Callers can pipe the real output without capturing errors.' },
    ],
    see: ['patterns-validate', 'patterns-exit-codes', 'special-parameters', 'exit-status'],
  },
  {
    name: 'Validate arguments', key: 'patterns-validate', kind: 'concept', aliases: ['validation', 'validate', 'validate arguments', 'valid input', 'check that a file exists', 'is a number', 'is an integer', 'is a directory', 'readable file', 'check input', 'input validation', 'sanity checks', 'integer check', 'check numeric', 'is numeric', 'file exists check'],
    summary: 'Check that an argument is what the script expects: existing file or directory, readable, integer, non-empty, within a range.',
    synopsis: ['[ -f "$1" ] || die "$1: not a file"', '[[ $n =~ ^[0-9]+$ ]] || die "$n: not a number"', '(( n >= 1 && n <= 10 )) || die "out of range"'],
    desc: ['Never assume the arguments are right. Validate in this order: **how many** (see the usage pattern), **is it present/non-empty** (`[ -n "$x" ]`), **its type** (`-f` file, `-d` directory, `-e` exists, `-r`/`-w`/`-x` permissions), **its format** (a regex such as `^[0-9]+$` for a non-negative integer, `^-?[0-9]+$` with a sign), **its range** (`(( ))`). Always **quote** the variable. Report **which** value was wrong, send errors to stderr and use a distinct exit status. To loop over many arguments, `continue` after reporting a bad one and remember the failure in a variable (`status=1`).'],
    sections: [{ title: 'The usual tests', table: [['Need', 'Test'], ['non-empty', '`[ -n "$x" ]`'], ['regular file', '`[ -f "$f" ]`'], ['directory', '`[ -d "$d" ]`'], ['readable / writable / executable', '`[ -r "$f" ]` `[ -w "$f" ]` `[ -x "$f" ]`'], ['integer ≥ 0', '`[[ $n =~ ^[0-9]+$ ]]`'], ['integer (signed)', '`[[ $n =~ ^-?[0-9]+$ ]]`'], ['decimal', '`[[ $n =~ ^[0-9]+(\\.[0-9]+)?$ ]]`'], ['in a range', '`(( n >= 1 && n <= 100 ))`'], ['one of a list', '`case $x in a|b|c) ok;; *) bad;; esac`'], ['a valid user / command', '`id "$u" >/dev/null 2>&1` / `command -v "$c" >/dev/null`']] }],
    examples: [
      { title: 'File checks with specific messages', cmd: 'check() {\n  [ -e "$1" ] || { echo "$1: does not exist" >&2; return 1; }\n  [ -f "$1" ] || { echo "$1: not a regular file" >&2; return 1; }\n  [ -r "$1" ] || { echo "$1: not readable" >&2; return 1; }\n  echo "$1: ok"\n}\ntouch good; mkdir dir; touch secret; chmod 000 secret\nfor f in good dir missing secret; do check "$f"; done', fails: true, note: 'The last check fails, so the example ends with status 1. Run as root, `secret` would be readable.' },
      { title: 'An integer', cmd: 'is_int() { [[ $1 =~ ^-?[0-9]+$ ]]; }\nfor v in 42 -3 3.14 abc ""; do\n  if is_int "$v"; then echo "[$v] integer"; else echo "[$v] not an integer"; fi\ndone' },
      { title: 'A number in a range', cmd: 'in_range() { [[ $1 =~ ^[0-9]+$ ]] && (( $1 >= $2 && $1 <= $3 )); }\nfor n in 5 0 11 x; do in_range "$n" 1 10 && echo "$n ok" || echo "$n invalid"; done' },
      { title: 'One of the allowed words', cmd: 'for mode in fast slow turbo; do\n  case $mode in\n    fast|slow) echo "$mode: valid" ;;\n    *) echo "$mode: invalid (use fast or slow)" ;;\n  esac\ndone' },
      { title: 'Report every bad argument, keep going', cmd: 'cat > s.sh << \'EOF\'\nstatus=0\nfor f in "$@"; do\n  if [ ! -f "$f" ]; then\n    echo "$0: $f: not a file" >&2\n    status=1\n    continue\n  fi\n  echo "$f: $(wc -l < "$f") lines"\ndone\nexit $status\nEOF\nprintf "a\\nb\\n" > ok.txt\nbash s.sh ok.txt missing /tmp; echo "status: $?"', fails: true },
      { title: 'Does a command or user exist?', cmd: 'command -v ls > /dev/null && echo "ls is available"\ncommand -v nosuchtool > /dev/null || echo "nosuchtool is missing"\nid root > /dev/null 2>&1 && echo "user root exists"\nid nosuchuser > /dev/null 2>&1 || echo "nosuchuser does not exist"' },
      { title: 'Not empty / not only spaces', cmd: 'for v in "text" "" "   "; do\n  if [[ -n ${v//[[:space:]]/} ]]; then echo "[$v]: has content"; else echo "[$v]: empty or blank"; fi\ndone' },
      { title: 'A date in YYYY-MM-DD form', cmd: 'valid_date() { [[ $1 =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] && date -d "$1" > /dev/null 2>&1; }\nfor d in 2024-02-29 2023-02-29 2024-13-01 hello; do valid_date "$d" && echo "$d valid" || echo "$d invalid"; done' },
    ],
    see: ['patterns-usage', 'test', 'regex', 'exit-status', 'patterns-exit-codes'],
  },
  {
    name: 'Default values', key: 'patterns-defaults', kind: 'concept', aliases: ['default directory', 'default dir', 'default argument', 'optional argument', 'optional arguments', 'default to current directory', '${1:-.}', '${2:-default}', 'defaults', 'default option'],
    summary: 'Give optional arguments and variables a default value: `${1:-default}`.',
    synopsis: ['dir=${1:-.}', 'count=${2:-10}', ': "${LOGFILE:=/tmp/app.log}"'],
    desc: ['`${var:-default}` expands to the value of `var` or to `default` when it is **unset or empty**. It is the way to make arguments optional: `dir=${1:-.}` uses the current directory when no argument was given; `n=${2:-10}` a count of 10. `:=` also **assigns** the default; `:?message` makes the script fail with the message if a **required** value is missing. Environment variables can supply defaults too (`dest=${BACKUP_DIR:-$HOME/backup}`), so a user can override them without options. Remember to quote: `"${1:-.}"`.'],
    examples: [
      { title: 'Optional directory (default: the current one)', cmd: 'cat > s.sh << \'EOF\'\ndir=${1:-.}\necho "listing $dir: $(ls "$dir" | wc -l) entries"\nEOF\nmkdir d; touch d/a d/b; touch x\nbash s.sh d\nbash s.sh' },
      { title: 'Several optional arguments', cmd: 'cat > s.sh << \'EOF\'\npattern=${1:?pattern is required}\ndir=${2:-.}\nmax=${3:-5}\necho "search $pattern in $dir, at most $max results"\nEOF\nbash s.sh txt\nbash s.sh txt /tmp 20\nbash s.sh 2>&1 | sed "s/line [0-9]*/line N/"', note: '`${1:?msg}` aborts with the message when the argument is missing.' },
      { title: 'Override through the environment', cmd: 'cat > s.sh << \'EOF\'\ndest=${BACKUP_DIR:-/tmp/backup}\necho "backing up to $dest"\nEOF\nbash s.sh\nBACKUP_DIR=/mnt/usb bash s.sh' },
      { title: 'Empty counts as unset with :-', cmd: 'v=""\necho "[${v:-default}] [${v-default}]"\nunset v\necho "[${v:-default}] [${v-default}]"' },
      { title: 'Assign the default once', cmd: 'unset OUT\n: "${OUT:=/tmp/out.txt}"\necho "OUT is now $OUT"' },
      { title: 'A default that depends on another value', cmd: 'name=${1:-$(whoami)}\necho "hello $name"\nset -- Ana\nname=${1:-$(whoami)}\necho "hello $name"' },
      { title: 'Check with a test instead', cmd: 'cat > s.sh << \'EOF\'\nif [ $# -ge 1 ]; then dir=$1; else dir=.; fi\necho "dir=$dir"\nEOF\nbash s.sh /tmp\nbash s.sh', note: 'The long form of the same idea.' },
    ],
    see: ['parameter-expansion', 'patterns-usage', 'patterns-validate', 'special-parameters'],
  },
  {
    name: 'Counters and tallies', key: 'patterns-counters', kind: 'concept', aliases: ['counters', 'counter', 'global counter', 'count successes', 'counting', 'count matches', 'count lines', 'tally', 'accumulate', 'accumulator', 'sum a list', 'running total', 'count occurrences', 'frequency', 'count per key', 'count by group', 'increment', '((n++))', 'count files'],
    summary: 'Count things in a loop: counters, sums, successes/failures, per-key tallies with associative arrays, and one-line counts with the pipeline tools.',
    synopsis: ['n=0; for ...; do n=$((n + 1)); done', 'declare -A seen; ((seen[$key]++))', 'sort | uniq -c | sort -rn'],
    desc: ['Start a counter at **0** before the loop, increment it inside (`n=$((n+1))` or `((n++))`), use it **after** the loop. Beware: a loop on the right side of a **pipe** runs in a subshell and the counter is lost; feed the loop with `< file` or `< <(cmd)` instead. To **count successes and failures** test the status of the command (`if cmd; then ok=$((ok+1)); else fail=$((fail+1)); fi`). To count **per key** use an **associative array** (`declare -A`); to count in one line without loops use `wc -l`, `grep -c`, or `sort | uniq -c`. Under `set -e` use `n=$((n+1))`, not `((n++))` (which returns status 1 when the old value was 0).'],
    examples: [
      { title: 'Count the files that match', cmd: 'touch a.txt b.txt c.log d.txt\ncount=0\nfor f in *.txt; do count=$((count + 1)); done\necho "$count text files"' },
      { title: 'Count successes and failures', cmd: 'ok=0; fail=0\nfor d in /tmp /nonexistent /etc /missing; do\n  if [ -d "$d" ]; then ok=$((ok + 1)); else fail=$((fail + 1)); fi\ndone\necho "$ok exist, $fail do not"' },
      { title: 'A sum', cmd: 'total=0\nfor n in 4 8 15 16 23 42; do total=$((total + n)); done\necho "total=$total"\nseq 1 100 | paste -sd+ | bc' },
      { title: 'Average (decimals need bc)', cmd: 'sum=0; n=0\nfor v in 7 8 10; do sum=$((sum + v)); n=$((n + 1)); done\necho "average: $(echo "scale=2; $sum / $n" | bc)"' },
      { title: 'Count the lines of a file inside a loop', cmd: 'printf "a\\nb\\nc\\n" > f\nn=0\nwhile IFS= read -r line; do n=$((n + 1)); done < f\necho "$n lines"\nn=0; cat f | while read -r l; do n=$((n+1)); done; echo "after a pipe: $n"', note: 'With a pipe the loop is a subshell, so the counter is lost.' },
      { title: 'Count per key (associative array)', cmd: 'declare -A count\nfor fruit in apple pear apple fig pear apple; do\n  count[$fruit]=$(( ${count[$fruit]:-0} + 1 ))\ndone\nfor k in "${!count[@]}"; do echo "$k: ${count[$k]}"; done | sort' },
      { title: 'The same with sort | uniq -c', cmd: 'printf "apple\\npear\\napple\\nfig\\npear\\napple\\n" | sort | uniq -c | sort -rn' },
      { title: 'Count words, lines, characters', cmd: 'printf "one two\\nthree\\n" > f\nwc -l < f; wc -w < f; wc -c < f' },
      { title: 'Count matching lines / occurrences', cmd: 'printf "a a\\nb\\na\\n" > f\ngrep -c a f\ngrep -o a f | wc -l', note: '`grep -c` counts lines; `grep -o | wc -l` counts occurrences.' },
      { title: 'Count by owner, by extension', cmd: 'touch a.txt b.txt c.sh d.sh e.sh\nfor f in *.*; do echo "${f##*.}"; done | sort | uniq -c' },
      { title: 'Only the first N matches', cmd: 'n=0\nfor i in $(seq 1 100); do\n  (( i % 7 == 0 )) || continue\n  n=$((n + 1)); echo -n "$i "\n  [ $n -eq 5 ] && break\ndone; echo' },
    ],
    see: ['while', 'for', 'arrays', 'uniq', 'arithmetic', 'patterns-read-lines'],
  },
  {
    name: 'Read a file line by line', key: 'patterns-read-lines', kind: 'concept', aliases: ['read lines', 'read a file line by line', 'process lines', 'line by line', 'csv processing', 'parse csv', 'header info', 'skip header', 'read fields', 'process each line', 'loop over lines', 'file processing', 'read file', 'while read pattern', 'read -r pattern'],
    summary: 'The `while IFS= read -r line` loop, splitting each line into fields, skipping headers and comments, handling the last unterminated line.',
    synopsis: ['while IFS= read -r line; do ...; done < FILE', 'while IFS=: read -r a b c; do ...; done < FILE', 'tail -n +2 FILE | while ...'],
    desc: ['**The idiom**: `while IFS= read -r line; do ...; done < file`. `read` returns non-zero at end of file; `IFS=` keeps leading/trailing blanks; `-r` keeps backslashes; the redirection `< file` is attached to the **loop** so it runs in the current shell (variables survive). To split a line into **fields** set `IFS` for `read` only: `IFS=, read -r name age city`; the last variable collects the rest. To **skip a header** use `tail -n +2 file | ...` (and `< <(...)` to keep the shell) or a flag/`NR` test; to skip **comments and blank lines** `case $line in ""|\\#*) continue;; esac`. A last line **without a trailing newline** needs `|| [ -n "$line" ]`. For simple column work `awk`/`cut` are shorter; use the loop when you must run commands per line.'],
    examples: [
      { title: 'Each line', cmd: 'printf "first\\n  second with spaces\\nthird\\n" > f\nwhile IFS= read -r line; do echo "[$line]"; done < f' },
      { title: 'Fields of a CSV / passwd-style file', cmd: 'printf "ana,30,madrid\\nluis,25,lima\\n" > people.csv\nwhile IFS=, read -r name age city; do\n  echo "$name ($age) lives in $city"\ndone < people.csv' },
      { title: 'Skip the header line', cmd: 'printf "name,age\\nana,30\\nluis,25\\n" > d.csv\nwhile IFS=, read -r name age; do echo "$name is $age"; done < <(tail -n +2 d.csv)' },
      { title: 'Skip comments and blank lines', cmd: 'printf "# comment\\nkeep 1\\n\\n  # indented comment\\nkeep 2\\n" > conf\nwhile IFS= read -r line; do\n  case $line in ""|"#"*|*"#"*) continue ;; esac\n  echo "line: $line"\ndone < conf', note: 'Here any line containing `#` is skipped; adapt the pattern.' },
      { title: 'Line numbers', cmd: 'printf "a\\nb\\nc\\n" > f\nn=0\nwhile IFS= read -r line; do n=$((n + 1)); printf "%2d: %s\\n" "$n" "$line"; done < f' },
      { title: 'A file without a final newline', cmd: 'printf "one\\ntwo" > f\nwhile IFS= read -r line || [ -n "$line" ]; do echo "[$line]"; done < f' },
      { title: 'Process with a command per line', cmd: 'printf "/tmp\\n/nonexistent\\n/etc\\n" > dirs\nwhile IFS= read -r d; do\n  if [ -d "$d" ]; then echo "$d: $(ls "$d" | wc -l) entries" | sed "s/[0-9]* entries/N entries/"; else echo "$d: missing"; fi\ndone < dirs' },
      { title: 'Sum a column', cmd: 'printf "a 10\\nb 20\\nc 5\\n" > f\ntotal=0\nwhile read -r name value; do total=$((total + value)); done < f\necho "total: $total"\nawk \'{s += $2} END {print s}\' f' },
      { title: 'Read two files in parallel', cmd: 'printf "a\\nb\\n" > f1; printf "1\\n2\\n" > f2\nwhile IFS= read -r x <&3 && IFS= read -r y <&4; do echo "$x$y"; done 3< f1 4< f2' },
      { title: 'Keep a variable set inside the loop', cmd: 'printf "x\\ny\\nz\\n" > f\nlast=""\nwhile IFS= read -r line; do last=$line; done < f\necho "last line: $last"' },
      { title: 'Lines into an array first', cmd: 'printf "one\\ntwo\\nthree\\n" > f\nmapfile -t lines < f\necho "${#lines[@]} lines; the second is ${lines[1]}"' },
    ],
    see: ['while', 'read', 'word-splitting', 'patterns-counters', 'cut', 'awk'],
  },
  {
    name: 'Loop over files with find', key: 'patterns-find-loop', kind: 'concept', aliases: ['find -print0 read loop', 'find loop', 'loop over find results', 'safe file names', 'files with spaces', 'filenames with spaces', 'find | while read', 'find exec pattern', 'find -exec sh -c', 'process each file', 'per-file operation', 'recursive loop', 'null-delimited'],
    summary: 'Run something for every file found: `find -exec`, `find | xargs`, and the safe `find -print0 | while read -d ""` loop (names with spaces and newlines).',
    synopsis: ['find DIR -type f -name "*.log" -exec CMD {} +', 'find DIR -type f -print0 | xargs -0 CMD', 'find DIR -type f -print0 | while IFS= read -r -d \'\' f; do ...; done', 'while ...; done < <(find DIR -type f -print0)'],
    desc: ['File names may contain spaces, tabs, quotes or even newlines; only the **NUL** byte cannot appear. So the robust ways to process the output of `find` are: **(1) `-exec CMD {} +`** (no shell loop needed; one command, many files) or `-exec CMD {} \\;` (one command per file); **(2) `-print0` with `xargs -0`**; **(3) `-print0` into a `while IFS= read -r -d \'\' f` loop**, which lets you use shell code per file. Use `< <(find ...)` (process substitution) instead of a pipe when the loop must change variables of the script. Never parse `ls` and never `for f in $(find ...)` — both split names at spaces. A plain `for f in *` (or `**` with `globstar`) is fine inside one directory.'],
    examples: [
      { title: 'A command on every file: -exec ... +', cmd: 'mkdir -p d/sub; echo one > d/a.txt; echo two > d/sub/b.txt\nfind d -name "*.txt" -exec wc -l {} + | sort', note: '`+` passes as many files as fit to one `wc`; `\\;` runs it once per file.' },
      { title: 'Shell code per file: -exec sh -c', cmd: 'touch a.tmp b.tmp\nfind . -name "*.tmp" -exec sh -c \'for f; do mv "$f" "${f%.tmp}.bak"; done\' _ {} +\nls', note: 'Inside `sh -c`, the files arrive as `"$@"` (`$0` is the placeholder `_`).' },
      { title: 'The safe loop: -print0 and read -d', cmd: 'touch "my file.txt" "other.txt" $\'new\\nline.txt\'\nfind . -name "*.txt" -print0 | while IFS= read -r -d \'\' f; do\n  printf "found: %q\\n" "$f"\ndone | sort', note: 'It works for any name, even with a newline. The `%q` shows the exact name.' },
      { title: 'Keep the counter: process substitution', cmd: 'touch a.c b.c c.c\nn=0\nwhile IFS= read -r -d \'\' f; do n=$((n + 1)); done < <(find . -name "*.c" -print0)\necho "$n files"', note: 'A pipe into `while` would have lost `n`.' },
      { title: 'xargs -0', cmd: 'touch "a b.log" c.log keep.txt\nfind . -name "*.log" -print0 | xargs -0 rm\nls' },
      { title: 'Without -print0 the names are split', cmd: 'touch "a b.tmp"\nfind . -name "*.tmp" | xargs ls 2>&1 | head -n 2\nfind . -name "*.tmp" -print0 | xargs -0 ls', fails: false, note: 'The first form passes `./a` and `b.tmp` as two names.' },
      { title: 'Filter first, act after', cmd: 'touch -d "40 days ago" old1.log old2.log; touch new.log\nfind . -name "*.log" -mtime +30 -print\nfind . -name "*.log" -mtime +30 -delete\nls' },
      { title: 'Total size per extension', cmd: 'echo aaa > a.txt; echo bbbbb > b.txt; echo cc > c.log\nfind . -type f -printf "%f %s\\n" | awk \'{n = split($1, p, "."); ext[p[n]] += $2} END {for (e in ext) print e, ext[e]}\' | sort' },
      { title: 'A glob when one directory is enough', cmd: 'touch "a b.txt" c.txt\nfor f in *.txt; do echo "[$f]"; done' },
      { title: 'Recursive glob', cmd: 'mkdir -p x/y; touch x/1.c x/y/2.c\nshopt -s globstar\nfor f in **/*.c; do echo "$f"; done' },
    ],
    see: ['find', 'xargs', 'while', 'process-substitution', 'patterns-read-lines', 'glob'],
  },
  {
    name: 'Parse options', key: 'patterns-options', kind: 'concept', aliases: ['options', 'option parsing loop', 'getopts-style option loop', 'parse options by hand', 'command line options', 'flags', 'long options', '--help', '--verbose', 'option -d', 'option -e', 'option -f', 'argument parsing', 'parse arguments', 'optional flags'],
    summary: 'Handle options like `-v`, `-o FILE`, `--help` and then the remaining arguments: `getopts` or a `while`/`case`/`shift` loop.',
    synopsis: ['while getopts "vo:h" opt; do case $opt in ...; esac; done; shift $((OPTIND-1))', 'while [ $# -gt 0 ]; do case $1 in -v) ...;; -o) out=$2; shift;; --) shift; break;; *) break;; esac; shift; done'],
    desc: ['Two standard ways. **`getopts`** (POSIX; single-letter options; letters followed by `:` take a value in `$OPTARG`; afterwards `shift $((OPTIND - 1))` leaves the non-option arguments). **A manual `while`/`case`/`shift` loop**, which also supports long options (`--output=FILE`, `--help`) and options after arguments. In both: set **defaults** before the loop, handle **unknown options** and **missing values** with an error and status 2, accept `--` as "end of options", and keep the loop order: *options first, then files*.'],
    examples: [
      { title: 'getopts', cmd: 'cat > s.sh << \'EOF\'\nverbose=0; out=stdout\nwhile getopts ":vo:" opt; do\n  case $opt in\n    v) verbose=1 ;;\n    o) out=$OPTARG ;;\n    \\?) echo "unknown option -$OPTARG" >&2; exit 2 ;;\n    :) echo "-$OPTARG needs a value" >&2; exit 2 ;;\n  esac\ndone\nshift $((OPTIND - 1))\necho "verbose=$verbose out=$out files=$*"\nEOF\nbash s.sh -v -o res.txt a b\nbash s.sh a b\nbash s.sh -x; echo "status: $?"', fails: true },
      { title: 'A manual loop with long options', cmd: 'cat > s.sh << \'EOF\'\nverbose=0; out=""\nwhile [ $# -gt 0 ]; do\n  case $1 in\n    -v|--verbose) verbose=1 ;;\n    -o|--output)  out=$2; shift ;;\n    --output=*)   out=${1#*=} ;;\n    -h|--help)    echo "usage: $0 [-v] [-o FILE] ARGS"; exit 0 ;;\n    --)           shift; break ;;\n    -*)           echo "unknown option: $1" >&2; exit 2 ;;\n    *)            break ;;\n  esac\n  shift\ndone\necho "verbose=$verbose out=${out:-none} rest: $*"\nEOF\nbash s.sh -v --output=r.txt a b\nbash s.sh -o x -- -weird file\nbash s.sh --help', note: '`--output=r.txt` is split with `${1#*=}`.' },
      { title: 'A value that must exist', cmd: 'cat > s.sh << \'EOF\'\nwhile getopts ":n:" opt; do\n  case $opt in\n    n) [[ $OPTARG =~ ^[0-9]+$ ]] || { echo "-n needs a number, got $OPTARG" >&2; exit 2; }\n       n=$OPTARG ;;\n    :) echo "-$OPTARG needs a value" >&2; exit 2 ;;\n  esac\ndone\necho "n=${n:-10}"\nEOF\nbash s.sh -n 5; bash s.sh -n abc; echo "status: $?"; bash s.sh', fails: true },
      { title: 'Options can be grouped', cmd: 'cat > s.sh << \'EOF\'\nwhile getopts "abc" o; do echo -n "$o "; done; echo\nEOF\nbash s.sh -abc\nbash s.sh -a -c' },
      { title: 'Required option', cmd: 'cat > s.sh << \'EOF\'\nwhile getopts "f:" o; do [ "$o" = f ] && file=$OPTARG; done\n[ -n "${file:-}" ] || { echo "usage: $0 -f FILE" >&2; exit 2; }\necho "file=$file"\nEOF\nbash s.sh; echo "status: $?"\nbash s.sh -f data', fails: true },
    ],
    see: ['getopts', 'shift', 'case', 'patterns-usage', 'special-parameters'],
  },
  {
    name: 'String recipes', key: 'patterns-strings', kind: 'concept', aliases: ['string slicing / case', 'string slicing', 'strings', 'string length', 'upper case', 'lower case', 'capitalize', 'trim', 'trim spaces', 'reverse a string', 'repeat a character', 'extension', 'file extension', 'file name without extension', 'split a string', 'join strings', 'palindrome', 'count characters', 'replace in string', 'string contains', 'starts with', 'ends with', 'pad a string', 'padding'],
    summary: 'The common string jobs without extra programs: length, slice, case, trim, replace, extension, split, join, reverse, repeat, padding, contains/starts/ends.',
    synopsis: ['${#s}  ${s:2:3}  ${s^^}  ${s,,}  ${s/old/new}  ${s//old/new}  ${s%.*}  ${s##*/}', '[[ $s == *sub* ]]  [[ $s == pre* ]]  [[ $s == *suf ]]'],
    desc: ['Most string jobs are one parameter expansion; reach for `sed`, `tr`, `cut` or `awk` only for patterns that are regular expressions or for whole files. Remember **patterns in `${ }` are globs**, `%`/`#` cut from the end/start, and that everything must be **quoted**.'],
    examples: [
      { title: 'Length and slices', cmd: 's="Hello, world"\necho "${#s}"\necho "${s:7}"\necho "${s:0:5}"\necho "${s: -5}"\necho "${s:0:1}"' },
      { title: 'Upper, lower, capitalize', cmd: 's="hello World"\necho "${s^^}"; echo "${s,,}"; echo "${s^}"\nw=mIxEd; w=${w,,}; echo "${w^}"' },
      { title: 'Replace', cmd: 's="the cat and the hat"\necho "${s/the/a}"\necho "${s//the/a}"\necho "${s//[aeiou]/*}"\necho "${s// /_}"' },
      { title: 'Contains / starts with / ends with', cmd: 's="report_2024.txt"\n[[ $s == *2024* ]] && echo "contains 2024"\n[[ $s == report* ]] && echo "starts with report"\n[[ $s == *.txt ]] && echo "ends with .txt"\n[[ $s != *.csv ]] && echo "is not a csv"' },
      { title: 'File name pieces', cmd: 'p=/home/ana/docs/archive.tar.gz\necho "dir:  ${p%/*}"\necho "file: ${p##*/}"\nf=${p##*/}\necho "ext:  ${f##*.}"\necho "base: ${f%%.*}"\necho "no last ext: ${f%.*}"' },
      { title: 'Trim blanks', cmd: 's="   padded text   "\ntrimmed=${s#"${s%%[![:space:]]*}"}\ntrimmed=${trimmed%"${trimmed##*[![:space:]]}"}\necho "[$trimmed]"\necho "$s" | sed -E "s/^ +| +$//g" | sed "s/.*/[&]/"\necho $s | sed "s/.*/[&]/"', note: 'The last line shows the trick: an unquoted `echo $s` collapses blanks.' },
      { title: 'Split and join', cmd: 'IFS=, read -ra parts <<< "red,green,blue"\necho "${parts[1]} (${#parts[@]} parts)"\n( IFS=-; echo "${parts[*]}" )\nprintf "%s\\n" "${parts[@]}" | paste -sd"+"' },
      { title: 'Reverse and palindromes', cmd: 'w=level\n[ "$w" = "$(echo "$w" | rev)" ] && echo "$w is a palindrome"\necho "stressed" | rev\nrev_s() { local s=$1 r=""; for (( i=${#s}-1; i>=0; i-- )); do r+=${s:i:1}; done; echo "$r"; }; rev_s hello' },
      { title: 'Repeat a character and pad', cmd: 'printf "%0.s-" {1..20}; echo\nprintf "%*s\\n" 10 "" | tr " " "="\nprintf "%-10s|\\n" abc\nprintf "%05d\\n" 42' },
      { title: 'Count a character', cmd: 's="banana"\necho "${s//[^a]/}" | wc -c | awk \'{print $1 - 1}\'\ntr -cd a <<< "$s" | wc -c', note: 'Delete everything except the letter, then count what is left.' },
      { title: 'Characters one by one', cmd: 's=abc\nfor (( i=0; i<${#s}; i++ )); do echo "${s:i:1}"; done\nfold -w1 <<< "$s"' },
      { title: 'Is it all digits / all letters?', cmd: 'for v in 12345 12a45 abc; do\n  [[ $v =~ ^[0-9]+$ ]] && echo "$v: digits" ; [[ $v =~ ^[[:alpha:]]+$ ]] && echo "$v: letters"\ndone; true' },
      { title: 'First word, last word', cmd: 's="the quick brown fox"\nset -- $s\necho "first: $1 last: ${!#}"\necho "${s%% *} / ${s##* }"' },
    ],
    see: ['parameter-expansion', 'tr', 'sed', 'cut', 'printf', 'patterns-validate'],
  },
  {
    name: 'Nested loops and tables', key: 'patterns-nested', kind: 'concept', aliases: ['nested for', 'nested loops', 'nested loop', 'multiplication table', 'triangle', 'patterns', 'draw a pattern', 'loops inside loops', 'grid', 'matrix', 'pyramid', 'nested while'],
    summary: 'A loop inside a loop: tables, triangles and grids; `break 2` and `continue 2`.',
    synopsis: ['for i in ...; do for j in ...; do ...; done; done', 'break 2'],
    desc: ['The inner loop runs **completely** for every iteration of the outer one. Typical uses: multiplication tables, drawing shapes with characters, combining two lists, comparing every pair of items. Use different variable names (`i`, `j`), print a newline after each inner loop, and leave both loops with `break 2`. `printf` makes tidy columns.'],
    examples: [
      { title: 'A multiplication table', cmd: 'for i in 1 2 3; do\n  for j in 1 2 3 4; do printf "%4d" $((i * j)); done\n  echo\ndone' },
      { title: 'A triangle', cmd: 'for (( i=1; i<=4; i++ )); do\n  for (( j=1; j<=i; j++ )); do echo -n "*"; done\n  echo\ndone' },
      { title: 'A pyramid', cmd: 'n=4\nfor (( i=1; i<=n; i++ )); do\n  printf "%*s" $((n - i)) ""\n  for (( j=1; j<=2*i-1; j++ )); do echo -n "#"; done\n  echo\ndone' },
      { title: 'Every combination of two lists', cmd: 'for colour in red blue; do\n  for size in S M L; do echo -n "$colour-$size "; done\ndone; echo' },
      { title: 'Leave both loops', cmd: 'for i in 1 2 3; do\n  for j in 1 2 3; do\n    if (( i * j == 6 )); then echo "found $i x $j"; break 2; fi\n  done\ndone' },
      { title: 'continue 2: next outer iteration', cmd: 'for i in 1 2 3; do\n  for j in 1 2 3; do\n    (( j == 2 )) && continue 2\n    echo "i=$i j=$j"\n  done\ndone' },
      { title: 'A chessboard', cmd: 'for r in 1 2 3 4; do\n  for c in 1 2 3 4 5 6 7 8; do (( (r + c) % 2 )) && echo -n "#" || echo -n "."; done\n  echo\ndone' },
      { title: 'Primes with two loops', cmd: 'for n in $(seq 2 30); do\n  prime=1\n  for (( d=2; d*d<=n; d++ )); do (( n % d == 0 )) && { prime=0; break; }; done\n  (( prime )) && echo -n "$n "\ndone; echo' },
      { title: 'Compare every pair', cmd: 'a=(3 1 2)\nfor i in "${a[@]}"; do for j in "${a[@]}"; do (( i < j )) && echo -n "$i<$j "; done; done; echo' },
      { title: 'Directories and their files', cmd: 'mkdir d1 d2; touch d1/a d1/b d2/c\nfor d in d1 d2; do\n  echo "$d:"\n  for f in "$d"/*; do echo "  ${f##*/}"; done\ndone' },
    ],
    see: ['for', 'break', 'while', 'printf', 'arithmetic'],
  },
  {
    name: 'Recursion and variable scope', key: 'patterns-recursion', kind: 'concept', aliases: ['recursive function', 'recursion', 'recursive', 'scope', 'variable scope', 'local scope', 'global variables', 'local vs global', 'factorial', 'fibonacci', 'recursive directory walk', 'function calls itself'],
    summary: 'Functions that call themselves (factorial, directory walk) and how `local` keeps each call\'s variables separate.',
    synopsis: ['fact() { local n=$1; (( n <= 1 )) && { echo 1; return; }; echo $(( n * $(fact $((n-1))) )); }'],
    desc: ['A **recursive function** has a **base case** that stops the recursion and a step that calls itself with a smaller problem. Every call needs its **own copies** of its variables: declare them with **`local`**, otherwise the inner call overwrites the outer one\'s values. Results are returned by **printing** them (the caller captures with `$( )`) or via a global variable. Each `$( )` starts a subshell: recursion by command substitution is slow for deep or wide problems — an iterative loop is often better. Variables set in a function **without** `local` are global; variables inside `$( )` or a pipeline are lost when it ends (scope = subshell).'],
    examples: [
      { title: 'Factorial', cmd: 'fact() {\n  local n=$1\n  if (( n <= 1 )); then echo 1; return; fi\n  echo $(( n * $(fact $((n - 1))) ))\n}\nfact 5\nfact 10' },
      { title: 'Without local the calls interfere', cmd: 'bad() { n=$1; (( n > 0 )) && { bad $((n - 1)); echo -n "$n "; }; }\nbad 3; echo\ngood() { local n=$1; (( n > 0 )) && { good $((n - 1)); echo -n "$n "; }; }\ngood 3; echo', note: 'In `bad`, `n` is global: every call sees the value set by the deepest call.' },
      { title: 'Fibonacci (recursive and iterative)', cmd: 'fib() { local n=$1; (( n < 2 )) && { echo "$n"; return; }; echo $(( $(fib $((n-1))) + $(fib $((n-2))) )); }\nfib 10\nfibi() { local a=0 b=1 i; for ((i=0; i<$1; i++)); do local t=$((a+b)); a=$b; b=$t; done; echo $a; }\nfibi 30' },
      { title: 'Walk a directory tree', cmd: 'mkdir -p top/a/b top/c; touch top/f1 top/a/f2 top/a/b/f3\nwalk() {\n  local dir=$1 indent=$2 e\n  for e in "$dir"/*; do\n    [ -e "$e" ] || continue\n    echo "$indent${e##*/}"\n    if [ -d "$e" ]; then walk "$e" "$indent  "; fi\n  done\n}\nwalk top ""', note: 'The `[ -e "$e" ] || continue` guard handles empty directories (where the glob stays literal).' },
      { title: 'Sum the digits of a number', cmd: 'digits() { local n=$1; if (( n < 10 )); then echo "$n"; else echo $(( n % 10 + $(digits $((n / 10))) )); fi; }\ndigits 12345' },
      { title: 'Power and greatest common divisor', cmd: 'pow() { local b=$1 e=$2; (( e == 0 )) && { echo 1; return; }; echo $(( b * $(pow "$b" $((e - 1))) )); }\npow 2 10\ngcd() { local a=$1 b=$2; (( b == 0 )) && { echo "$a"; return; }; gcd "$b" $((a % b)); }\ngcd 48 18' },
      { title: 'Scope: a variable in $( ) is lost', cmd: 'count=0\nincr() { count=$((count + 1)); }\nincr; incr\necho "direct calls: $count"\n( incr; incr ); echo "after a subshell: $count"\nx=$(incr; echo $count); echo "inside \\$( ): $x, after: $count"' },
      { title: 'Function arguments hide the script\'s', cmd: 'cat > s.sh << \'EOF\'\nshow() { echo "in function: $1"; }\necho "script: $1"\nshow other\necho "script again: $1"\nEOF\nbash s.sh original' },
      { title: 'Depth limit of recursion', cmd: 'depth() { (( $1 > 0 )) && depth $(($1 - 1)); }\ndepth 200; echo "200 levels ok"', note: 'Bash allows deep recursion (the stack may eventually run out: `FUNCNEST` can limit it).' },
    ],
    see: ['functions', 'declare', 'command-substitution', 'arithmetic', 'patterns-nested'],
  },
  {
    name: 'Meaningful exit codes', key: 'patterns-exit-codes', kind: 'concept', aliases: ['distinct exit codes', 'exit code convention', 'error handling', 'return codes of a script', 'handle errors', 'check command success', 'status codes', 'exit code per error', 'check $? pattern', 'fail fast', 'check cd', 'cd || exit'],
    summary: 'Give each kind of failure its own exit status, check commands that can fail, and let the caller react.',
    synopsis: ['cd "$dir" || exit 1', 'exit 3   # with a documented meaning', 'if ! cmd; then ...; fi'],
    desc: ['A script that fails must say so through its **exit status**, so other scripts, `cron` and `&&` chains can react. Conventions: **0** success; **1** general error; **2** misuse (wrong arguments); further numbers (3, 4, ... up to 125) for each failure the caller might want to distinguish — document them in a comment. **Check commands that can fail** (`cd`, `cp`, `mkdir`, `rm` ...): `cd "$d" || exit 1` — a failed `cd` followed by `rm -rf *` is a classic disaster. Report on **stderr** with the script name. When looping over several items keep going, remember that something failed, and exit non-zero at the end.'],
    examples: [
      { title: 'A different status per problem', cmd: 'cat > s.sh << \'EOF\'\n# exit codes: 0 ok, 2 usage, 3 not found, 4 not readable\n[ $# -eq 1 ] || { echo "usage: $0 FILE" >&2; exit 2; }\n[ -e "$1" ] || { echo "$1: not found" >&2; exit 3; }\n[ -r "$1" ] || { echo "$1: not readable" >&2; exit 4; }\necho "$1 is fine"\nEOF\ntouch ok; touch locked; chmod 000 locked\nfor args in "" nofile ok locked; do bash s.sh $args > /dev/null 2>&1; echo "[$args] -> $?"; done', note: 'The caller can `case $?` on those values. (As root `locked` would be readable.)' },
      { title: 'Check the commands that can fail', cmd: 'cat > s.sh << \'EOF\'\ncd /nonexistent || { echo "cannot enter the directory" >&2; exit 1; }\necho "this would delete the wrong files: rm -rf ./*"\nEOF\nbash s.sh; echo "status: $?"', fails: true },
      { title: 'Failures in a loop: continue, then report', cmd: 'cat > s.sh << \'EOF\'\nstatus=0\nfor d in /tmp /nonexistent /etc; do\n  if [ ! -d "$d" ]; then echo "$d: missing" >&2; status=1; continue; fi\n  echo "$d ok"\ndone\nexit $status\nEOF\nbash s.sh; echo "status: $?"', fails: true },
      { title: 'React to the status of a command', cmd: 'if cp /nonexistent dest 2>/dev/null; then echo "copied"; else echo "copy failed (status $?)"; fi\nmkdir newd && echo "created" || echo "could not create"' },
      { title: 'Save $? before it changes', cmd: 'grep -q zzz /etc/passwd\nstatus=$?\necho "grep said $status"\ncase $status in 0) echo found;; 1) echo "not found";; *) echo error;; esac' },
      { title: 'A case on the caller side', cmd: 'cat > check.sh << \'EOF\'\nexit 3\nEOF\nbash check.sh\ncase $? in\n  0) echo "all good" ;;\n  2) echo "bad usage" ;;\n  3) echo "file missing" ;;\n  *) echo "unexpected failure" ;;\nesac' },
      { title: 'Stop on the first error (set -e) and what escapes it', cmd: 'bash -c \'set -e; echo one; false; echo two\'; echo "status: $?"\nbash -c \'set -e; if false; then :; fi; false || true; echo "survives"\'', fails: true },
      { title: 'A cleanup that must run anyway', cmd: 'bash -c \'trap "echo cleanup done" EXIT; echo working; exit 5\'; echo "status: $?"', fails: true },
    ],
    see: ['exit-status', 'patterns-usage', 'if', 'trap', 'set'],
  },
  {
    name: 'Temporary files and cleanup', key: 'patterns-tempfiles', kind: 'concept', aliases: ['temporary files', 'temp files', 'mktemp pattern', 'cleanup on exit', 'trap cleanup pattern', 'temp dir', 'temporary directory', 'safe temp file', 'scratch directory'],
    summary: 'Create a unique temporary file or directory with `mktemp` and delete it with a `trap ... EXIT`, whatever happens.',
    synopsis: ['tmp=$(mktemp)   tmpdir=$(mktemp -d)', 'trap \'rm -rf "$tmp" "$tmpdir"\' EXIT'],
    desc: ['Never use fixed names like `/tmp/out`: two runs would collide and others could guess the name. `mktemp` gives a unique, private (600) file (`-d`: directory). Register the removal **immediately** with `trap ... EXIT`, so it happens on a normal end, an `exit`, an error under `set -e` and `Ctrl-C` (add `INT TERM` if you want a distinct status). Use single quotes for the trap command so the variable is evaluated when it fires. Write the result to the temp file first and only `mv` it over the target when complete: a crash never leaves a half-written file (an atomic update).'],
    examples: [
      { title: 'A temporary file removed at the end', cmd: 'tmp=$(mktemp)\ntrap \'rm -f "$tmp"\' EXIT\nseq 1 5 > "$tmp"\nwc -l < "$tmp"\n[ -f "$tmp" ] && echo "still there while the script runs"' },
      { title: 'A temporary directory', cmd: 'work=$(mktemp -d)\ntrap \'rm -rf "$work"\' EXIT\necho data > "$work/a"; mkdir "$work/sub"\nfind "$work" -type f | wc -l\necho "$work" > path.txt' },
      { title: 'It really is cleaned up', cmd: 'cat > s.sh << \'EOF\'\ntmp=$(mktemp)\ntrap \'rm -f "$tmp"\' EXIT\necho "$tmp" > /tmp/where.txt\nexit 1\nEOF\nbash s.sh\n[ -e "$(cat /tmp/where.txt)" ] || echo "removed even though the script failed"; rm /tmp/where.txt', fails: false },
      { title: 'Edit a file safely (write to a temp file, then replace)', cmd: 'printf "b\\na\\nc\\n" > list\ntmp=$(mktemp)\nsort list > "$tmp" && mv "$tmp" list\ncat list', note: 'If `sort` fails the original is untouched.' },
      { title: 'A name template', cmd: 'f=$(mktemp backup.XXXXXX)\ncase $f in backup.??????) echo "unique name with a fixed prefix";; esac' },
      { title: 'Private by default', cmd: 'f=$(mktemp); stat -c %a "$f"; d=$(mktemp -d); stat -c %a "$d"; rm -r "$f" "$d"' },
    ],
    see: ['mktemp', 'trap', 'patterns-exit-codes', 'mv'],
  },
  {
    name: 'Create, copy and rename safely', key: 'patterns-files', kind: 'concept', aliases: ['create dir with message', 'create directory if missing', 'mkdir -p pattern', 'backup a file', 'backup with timestamp', 'timestamped backup', 'safe copy', 'safe overwrite', 'rename pattern', 'rename files', 'bulk rename', 'change extension', 'move files by type', 'organize files', 'file operations', 'check before overwrite', 'create if not exists', 'copy if newer'],
    summary: 'File-handling recipes: create a directory only if missing (with a message), back up with a date, rename in bulk, never overwrite by accident.',
    synopsis: ['[ -d "$d" ] || mkdir -p "$d"', 'cp "$f" "$f.$(date +%F).bak"', 'for f in *.txt; do mv "$f" "${f%.txt}.md"; done'],
    desc: ['The checks and the habits: **test before acting** (`[ -e ]`, `[ -d ]`), **say what you did** (a message per action helps users and logs), **do not overwrite silently** (`cp -n`, `mv -n`, or test first), **quote** every path, **handle failure** of each step, and build **unique/sortable names** with `date +%F` or `%Y%m%d_%H%M%S`.'],
    examples: [
      { title: 'Create a directory if it is missing, with a message', cmd: 'dir=reports\nif [ -d "$dir" ]; then\n  echo "$dir already exists"\nelse\n  mkdir -p "$dir" && echo "created $dir"\nfi\nif [ -d "$dir" ]; then echo "$dir already exists"; fi' },
      { title: 'mkdir -p is idempotent', cmd: 'mkdir -p a/b/c && echo "ok"\nmkdir -p a/b/c && echo "ok again"' },
      { title: 'Back up a file with the date', cmd: 'echo data > config\ncp config "config.$(date -d 2024-06-01 +%F).bak"\nls' },
      { title: 'Do not overwrite', cmd: 'echo old > dest; echo new > src\nif [ -e dest ]; then echo "dest exists, not overwriting"; else cp src dest; fi\ncp --update=none src dest; cat dest' },
      { title: 'Rename in bulk: change the extension', cmd: 'touch a.txt b.txt c.txt\nfor f in *.txt; do mv "$f" "${f%.txt}.md"; done\nls' },
      { title: 'Rename in bulk: add a prefix / number them', cmd: 'touch a.jpg b.jpg c.jpg\nn=1\nfor f in *.jpg; do mv "$f" "$(printf "photo_%03d.jpg" $n)"; n=$((n + 1)); done\nls' },
      { title: 'Lower-case all file names', cmd: 'touch README Notes.TXT\nfor f in *; do l=${f,,}; [ "$f" = "$l" ] || mv -n "$f" "$l"; done\nls' },
      { title: 'Organize files by extension', cmd: 'touch a.txt b.txt c.jpg d.jpg e.md\nfor f in *.*; do ext=${f##*.}; mkdir -p "$ext"; mv "$f" "$ext/"; done\nfind . -type f | sort' },
      { title: 'Copy only if the source is newer', cmd: 'touch -d 2024-01-01 old; touch -d 2024-06-01 new\ncp old target; touch -d 2024-03-01 target\nif [ new -nt target ]; then cp new target && echo "updated"; fi' },
      { title: 'Move files older than N days', cmd: 'mkdir old; touch -d "40 days ago" a.log b.log; touch c.log\nfind . -maxdepth 1 -name "*.log" -mtime +30 -exec mv -t old {} +\nls old; ls *.log' },
      { title: 'Count the files that could not be copied', cmd: 'mkdir dest; touch a b; failed=0\nfor f in a b missing; do cp "$f" dest/ 2>/dev/null || { echo "failed: $f"; failed=$((failed + 1)); }; done\necho "$failed failure(s)"' },
    ],
    see: ['cp', 'mv', 'mkdir', 'date', 'parameter-expansion', 'patterns-find-loop'],
  },
  {
    name: 'Menu and user input', key: 'patterns-menu', kind: 'concept', aliases: ['menu loop', 'menu pattern', 'interactive menu', 'ask a question', 'ask yes/no', 'confirm', 'yes no prompt', 'read input', 'prompt user', 'retry input', 'input loop', 'confirmation', 'ask until valid', 'repeat until'],
    summary: 'Ask the user something: yes/no confirmation, repeat until the answer is valid, and a menu loop with `select` or `case`.',
    synopsis: ['read -r -p "Continue? [y/N] " ans; [[ $ans == [yY]* ]] || exit 1', 'while true; do read -r -p "n: " n; [[ $n =~ ^[0-9]+$ ]] && break; done', 'select opt in a b quit; do case $opt in ...; esac; done'],
    desc: ['Interactive scripts use `read -p` to prompt. **Confirm** dangerous actions with a default of "no" (`[y/N]`: capital = default). **Validate** the answer and **ask again** in a loop until it is acceptable, with a way out. A **menu** can be a `while true` loop printing the options and a `case` on the answer, or `select` (automatic numbering, `PS3` prompt). Make scripts testable by reading from stdin (here-strings, pipes) and non-interactive when input is not a terminal.'],
    examples: [
      { title: 'Confirm before a dangerous action', cmd: 'confirm() { local ans; read -r -p "$1 [y/N] " ans; [[ $ans == [yY]* ]]; }\necho y | confirm "Delete everything?" && echo "deleting..."\necho n | confirm "Delete everything?" || echo "cancelled"\necho "" | confirm "Delete everything?" || echo "default is no"' },
      { title: 'Ask until the answer is valid', cmd: 'printf "abc\\n-5\\n42\\n" | {\n  while true; do\n    read -r -p "A positive number: " n\n    [[ $n =~ ^[0-9]+$ ]] && break\n    echo "not a positive number, try again"\n  done\n  echo "you typed $n"\n}', note: 'Here the three answers come from `printf`; at the terminal you type them.' },
      { title: 'A menu loop with case', cmd: 'while true; do\n  echo "1) list  2) date  3) quit"\n  read -r -p "choice: " c || break\n  case $c in\n    1) echo "(listing)" ;;\n    2) date -d 2024-06-01 +%F ;;\n    3) echo bye; break ;;\n    *) echo "invalid choice: $c" ;;\n  esac\ndone < <(printf "1\\nx\\n2\\n3\\n") 2>&1' },
      { title: 'select', cmd: 'PS3="option: "\nselect opt in start stop quit; do\n  case $opt in\n    start|stop) echo "you chose $opt" ;;\n    quit) break ;;\n    *) echo "invalid: $REPLY" ;;\n  esac\ndone < <(printf "1\\n7\\n3\\n") 2>&1' },
      { title: 'Read several values', cmd: 'read -r -p "name and age: " name age <<< "Ana 30"\necho "$name is $age"' },
      { title: 'A password without echo', cmd: 'read -r -s -p "Password: " pw < /dev/null; echo\necho "(not shown while typing)"', note: '`-s` hides the typing at a terminal.' },
      { title: 'A timeout with a default', cmd: 'sleep 2 | { read -r -t 0.3 -p "Name [guest]: " name; name=${name:-guest}; echo "using $name"; }' },
      { title: 'Interactive or not?', cmd: '[ -t 0 ] && echo "stdin is a terminal: ask the user" || echo "stdin is not a terminal: use defaults"' },
    ],
    see: ['read', 'select', 'case', 'while', 'patterns-validate'],
  },
  {
    name: 'Arithmetic recipes', key: 'patterns-math', kind: 'concept', aliases: ['leap years', 'leap year', 'bitwise & ~', 'even or odd', 'min max', 'maximum', 'minimum', 'prime numbers', 'gcd', 'sum of digits', 'number bases', 'base conversion', 'average', 'percentage', 'rounding', 'powers', 'math recipes', 'arithmetic puzzles', 'divisible', 'modulo pattern', 'octal permissions arithmetic', '$(( 8#... & ... ))', '$((10#...))', '10#', '$(( 10# ))', 'leading zeros', 'arithmetic with permissions'],
    summary: 'Small calculations scripts keep needing: even/odd, leap year, min/max, gcd, primes, digit sum, percentages, bases and bit masks (permission arithmetic).',
    synopsis: ['(( n % 2 == 0 ))   (( y % 4 == 0 && (y % 100 != 0 || y % 400 == 0) ))', '$(( a > b ? a : b ))   $(( 8#755 & 8#022 ))   $((10#$n))'],
    desc: ['Everything with **integers** is `$(( ))`/`(( ))`; decimals need `bc` or `awk`. Watch out for **leading zeros**: `08` is an invalid octal number — force base 10 with `$((10#$n))` (typical for hours and minutes from `date` or user input). **Bases**: `8#755`, `16#ff`, `2#1010`; print with `printf "%o %x"`. **Bit masks** (`& | ^ ~ << >>`) are how permissions and umask work: `$(( 8#666 & ~8#022 ))` is `644`.'],
    examples: [
      { title: 'Even or odd', cmd: 'for n in 7 10; do (( n % 2 == 0 )) && echo "$n even" || echo "$n odd"; done' },
      { title: 'Leap year', cmd: 'for y in 1900 2000 2023 2024; do\n  if (( y % 4 == 0 && (y % 100 != 0 || y % 400 == 0) )); then echo "$y leap"; else echo "$y not leap"; fi\ndone' },
      { title: 'Minimum and maximum', cmd: 'a=7; b=12\necho "max: $(( a > b ? a : b )) min: $(( a < b ? a : b ))"\nset -- 4 9 2 7\nmax=$1; for n; do (( n > max )) && max=$n; done; echo "max of list: $max"' },
      { title: 'Greatest common divisor', cmd: 'gcd() { local a=$1 b=$2 t; while (( b )); do t=$b; b=$((a % b)); a=$t; done; echo "$a"; }\ngcd 48 18\ngcd 17 5' },
      { title: 'Is it prime?', cmd: 'is_prime() { local n=$1 d; (( n < 2 )) && return 1; for (( d=2; d*d<=n; d++ )); do (( n % d == 0 )) && return 1; done; return 0; }\nfor n in 1 2 15 17 97; do is_prime $n && echo "$n prime" || echo "$n not prime"; done' },
      { title: 'Sum the digits', cmd: 'n=90210; sum=0\nwhile (( n > 0 )); do sum=$((sum + n % 10)); n=$((n / 10)); done; echo "$sum"\nn=1234; s=0; for (( i=0; i<${#n}; i++ )); do s=$((s + ${n:i:1})); done; echo "$s"' },
      { title: 'Percentage and rounding', cmd: 'part=37; total=120\necho "integer: $(( part * 100 / total ))%"\necho "two decimals: $(echo "scale=2; $part * 100 / $total" | bc)%"\nprintf "rounded: %.0f%%\\n" "$(echo "scale=4; $part * 100 / $total" | bc)"' },
      { title: 'Leading zeros are octal', cmd: 'h=08\necho $((10#$h + 1))\necho $((h + 1))', fails: true, note: '`08` is not valid octal, so the second line is an error; `10#` forces decimal (needed with the hours and minutes from `date`).' },
      { title: 'Bases', cmd: 'printf "%d in octal %o, hex %x, binary " 255 255 255; echo "obase=2; 255" | bc\necho $((2#1010)) $((16#ff)) $((8#755))' },
      { title: 'Permission arithmetic with masks', cmd: 'echo $(( 8#666 & ~8#022 ))  | xargs printf "%o\\n"\nmode=0754\nprintf "owner:%o group:%o others:%o\\n" $(( mode >> 6 & 7 )) $(( mode >> 3 & 7 )) $(( mode & 7 ))\n(( 8#754 & 8#001 )) && echo "others can execute" || echo "others cannot execute"' },
      { title: 'Time arithmetic', cmd: 'secs=3725\nprintf "%02d:%02d:%02d\\n" $((secs / 3600)) $((secs % 3600 / 60)) $((secs % 60))' },
      { title: 'Random in a range', cmd: 'r=$(( RANDOM % 6 + 1 )); (( r >= 1 && r <= 6 )) && echo "valid dice"' },
      { title: 'Table of squares and cubes', cmd: 'for i in 1 2 3 4; do printf "%d %3d %4d\\n" $i $((i**2)) $((i**3)); done' },
    ],
    see: ['arithmetic', 'bc', 'chmod', 'umask', 'printf', 'date'],
  },
  {
    name: 'Build a report', key: 'patterns-report', kind: 'concept', aliases: ['report', 'reports', 'summary line', 'formatted output', 'header and footer', 'table output', 'totals', 'print a table', 'summary report', 'report pattern', 'output format'],
    summary: 'Produce a tidy report: header, aligned rows with `printf`, totals and a summary line.',
    synopsis: ['printf "%-12s %8s\\n" NAME SIZE', 'printf "%-12s %8d\\n" "$name" "$size"', 'echo "Total: $n files, $bytes bytes"'],
    desc: ['A report script prints a **header**, one **row per item**, then a **footer** with totals. `printf` with widths (`%-12s` left-aligned text, `%8d` right-aligned number, `%8.2f` decimals) makes columns line up; compute totals with counters in the loop; separate the data gathering from the printing; send the whole output to a file with `{ ...; } > report.txt`, or pipe to `column -t` for automatic alignment.'],
    examples: [
      { title: 'A table with a total', cmd: 'echo aaaa > a.txt; echo bb > b.txt; head -c 3000 /dev/zero > big.bin\ntotal=0; count=0\nprintf "%-10s %8s\\n" NAME BYTES\nprintf "%-10s %8s\\n" ---------- --------\nfor f in a.txt b.txt big.bin; do\n  size=$(stat -c %s "$f")\n  printf "%-10s %8d\\n" "$f" "$size"\n  total=$((total + size)); count=$((count + 1))\ndone\nprintf "%-10s %8d\\n" TOTAL "$total"\necho "$count files"' },
      { title: 'Header and footer into a file', cmd: '{\n  echo "=== Report ==="\n  for i in 1 2 3; do printf "item %d: %s\\n" "$i" "$((i * i))"; done\n  echo "=== end ==="\n} > report.txt\ncat report.txt' },
      { title: 'Automatic alignment with column', cmd: 'printf "name,age,city\\nana,30,madrid\\nluis,5,lima\\n" | column -t -s,' },
      { title: 'Group and sum (awk)', cmd: 'printf "ana 10\\nluis 5\\nana 7\\n" | awk \'{sum[$1] += $2} END {for (n in sum) printf "%-6s %3d\\n", n, sum[n]}\' | sort' },
      { title: 'A summary line with several figures', cmd: 'seq 1 10 > n\nsum=$(paste -sd+ n | bc); count=$(wc -l < n)\necho "count=$count sum=$sum average=$(echo "scale=1; $sum / $count" | bc)"' },
      { title: 'Percent bars', cmd: 'for v in 10 45 80; do printf "%3d%% " "$v"; printf "%*s\\n" $((v / 5)) "" | tr " " "#"; done' },
      { title: 'Sorted report, biggest first', cmd: 'head -c 300 /dev/zero > a; head -c 50 /dev/zero > b; head -c 900 /dev/zero > c\nfor f in a b c; do echo "$(stat -c %s "$f") $f"; done | sort -rn | while read -r size name; do printf "%-5s %5d\\n" "$name" "$size"; done' },
      { title: 'Report with the date', cmd: 'echo "Report generated on $(date -d 2024-06-01 "+%A, %d %B %Y")"' },
    ],
    see: ['printf', 'column', 'awk', 'patterns-counters', 'sort'],
  },
  {
    name: 'Log analysis recipes', key: 'patterns-log-analysis', kind: 'concept', aliases: ['log analysis', 'analyze logs', 'parse logs', 'top N', 'top talkers', 'most frequent', 'count by ip', 'count requests', 'apache log', 'access log', 'failed logins', 'log filter', 'log pipeline', 'text processing pipeline', 'frequency count'],
    summary: 'Pipelines for log files: filter, extract a field, count per value, top N, per-hour totals.',
    synopsis: ['grep PATTERN log | cut -d" " -f1 | sort | uniq -c | sort -rn | head -n 5', 'awk \'{c[$1]++} END {for (k in c) print c[k], k}\' log | sort -rn'],
    desc: ['The recurring shape: **filter** the interesting lines (`grep`), **extract** the field (`cut`, `awk`, `grep -o`), **normalise** (`sort`), **count** (`uniq -c`), **rank** (`sort -rn`) and **limit** (`head`). Know your columns: web logs are space-separated (IP in field 1, status in field 9), syslog has the date in fields 1-3 and the host in 4. Use `LC_ALL=C sort` for predictable ordering and `awk` when you need arithmetic or several conditions.'],
    examples: [
      { title: 'A sample web-server log', cmd: SAMPLE_LOG + 'wc -l < access.log\ncut -c1-40 access.log' },
      { title: 'Requests per client (top N)', cmd: SAMPLE_LOG + 'cut -d" " -f1 access.log | sort | uniq -c | sort -rn | head -n 3' },
      { title: 'Count by status code', cmd: SAMPLE_LOG + 'awk \'{print $9}\' access.log | sort | uniq -c | sort -k2n' },
      { title: 'Only the errors (4xx/5xx)', cmd: SAMPLE_LOG + 'awk \'$9 >= 400\' access.log | cut -c1-60' },
      { title: 'Most requested pages', cmd: SAMPLE_LOG + 'grep -oE "\\"(GET|POST) [^ ]+" access.log | cut -d" " -f2 | sort | uniq -c | sort -rn' },
      { title: 'Requests per hour', cmd: SAMPLE_LOG + 'cut -d: -f2 access.log | sort | uniq -c' },
      { title: 'Total bytes sent', cmd: SAMPLE_LOG + 'awk \'{sum += $10} END {print sum " bytes"}\' access.log' },
      { title: 'One client\'s activity', cmd: SAMPLE_LOG + 'grep "^10.0.0.1 " access.log | wc -l\ngrep -c "^10.0.0.1 " access.log' },
      { title: 'Lines between two moments', cmd: SAMPLE_LOG + 'awk \'$4 >= "[01/Jun/2024:10:01" && $4 < "[01/Jun/2024:11:00"\' access.log | cut -c1-70' },
      { title: 'Syslog-style: failures per user', cmd: 'cat > auth.log << \'EOF\'\nJun  1 03:12:01 host sshd[1]: Failed password for root from 203.0.113.9 port 40122 ssh2\nJun  1 03:12:03 host sshd[1]: Failed password for admin from 203.0.113.9 port 40124 ssh2\nJun  1 03:12:09 host sshd[1]: Failed password for root from 198.51.100.7 port 51000 ssh2\nJun  1 09:00:00 host sshd[2]: Accepted password for ana from 192.168.1.20 port 51514 ssh2\nEOF\ngrep "Failed password" auth.log | awk \'{print $9}\' | sort | uniq -c | sort -rn\ngrep "Failed password" auth.log | grep -oE "from [0-9.]+" | sort | uniq -c' },
      { title: 'Watch a log for a pattern', cmd: 'echo "start" > live.log\n(sleep 0.5; echo "ERROR disk full" >> live.log; echo "ok" >> live.log) &\ntimeout 2 tail -f live.log | grep --line-buffered ERROR | head -n 1', note: '`--line-buffered` makes grep print immediately in a pipeline.' },
    ],
    see: ['grep', 'cut', 'sort', 'uniq', 'awk', 'logs', 'patterns-counters'],
  },
  {
    name: 'Retry and wait loops', key: 'patterns-retry', kind: 'concept', aliases: ['retry', 'retry loop', 'wait for', 'wait until', 'polling', 'timeout loop', 'wait for file', 'wait for a process', 'attempts', 'try again', 'wait loop'],
    summary: 'Try a command several times, wait for a file or a process, and give up after a limit.',
    synopsis: ['for i in 1 2 3; do cmd && break; sleep 1; done', 'until [ -e "$f" ]; do sleep 1; done', 'timeout 10 bash -c \'until cmd; do sleep 1; done\''],
    desc: ['Waiting for something that is not ready yet (a service, a file, a lock) is a loop that tests a condition, sleeps a little and counts attempts so it **cannot run forever**. Prefer a bounded `for` over `while true`, report the failure clearly and leave with a non-zero status when the attempts run out. `timeout` can bound a whole loop; `kill -0 PID` tests that a process still exists.'],
    examples: [
      { title: 'Retry up to N times', cmd: 'n=0\nattempt() { n=$((n + 1)); [ $n -ge 3 ]; }\nfor i in 1 2 3 4 5; do\n  if attempt; then echo "succeeded on attempt $i"; break; fi\n  echo "attempt $i failed"; sleep 0.1\ndone' },
      { title: 'Wait for a file, with a limit', cmd: '(sleep 0.4; touch ready) &\nfor i in $(seq 1 20); do\n  [ -e ready ] && { echo "the file appeared"; break; }\n  sleep 0.1\ndone\n[ -e ready ] || echo "gave up"' },
      { title: 'Give up and report', cmd: 'for i in 1 2 3; do [ -e never ] && break; sleep 0.1; done\n[ -e never ] || { echo "never appeared after 3 tries" >&2; exit 1; }' , fails: true },
      { title: 'Wait for a process to end', cmd: 'sleep 0.5 & pid=$!\nwhile kill -0 "$pid" 2>/dev/null; do sleep 0.1; done\necho "the process is gone"\nwait 2>/dev/null; true' },
      { title: 'Bound a whole loop with timeout', cmd: 'timeout 1 bash -c \'until [ -e never ]; do sleep 0.1; done\'; echo "status: $?"', fails: true, note: '124 means the time ran out.' },
      { title: 'Increasing delay (back-off)', cmd: 'delay=1\nfor i in 1 2 3; do echo "attempt $i, waiting ${delay}s next time"; delay=$((delay * 2)); done' },
      { title: 'Run until it works or print the last error', cmd: 'for i in 1 2 3; do\n  if out=$(ls /nonexistent 2>&1); then break; fi\n  sleep 0.1\ndone\necho "last error: $out"' },
    ],
    see: ['while', 'sleep', 'timeout', 'kill', 'wait', 'patterns-exit-codes'],
  },
]);
